fn rich_text_css() -> &'static str {
    r#".rich-text{--dowe-component-display:block;display:var(--dowe-show,var(--dowe-component-display));max-width:100%;width:100%;text-align:center;line-height:inherit;}.rich-mark{--rich-accent:var(--dowe-info);--rich-on-accent:var(--dowe-infoText);--rich-soft-accent:var(--dowe-softInfo);display:inline-block;box-sizing:border-box;max-width:100%;text-align:center;white-space:normal;overflow-wrap:normal;word-break:normal;position:relative;color:inherit;}.rich-mark-mark{border-radius:.125rem;background:var(--rich-accent);color:var(--rich-on-accent);padding:.125rem .5rem;font-weight:700;letter-spacing:.025em;text-transform:uppercase;transition:filter 300ms ease,transform 300ms ease;}.rich-mark-grad{background:linear-gradient(90deg,var(--rich-accent),color-mix(in oklch,var(--rich-accent) 60%,white));background-clip:text;-webkit-background-clip:text;-webkit-text-fill-color:transparent;color:transparent;padding-right:.15em;font-style:italic;font-weight:700;transition:filter 300ms ease;}.rich-mark-pill{border:2px solid var(--rich-accent);border-radius:9999px;color:var(--rich-accent);padding:.125rem .625rem;font-weight:600;transition:background-color 300ms ease,transform 300ms ease;}.rich-mark-slant{isolation:isolate;z-index:0;color:var(--rich-on-accent);font-weight:700;}.rich-mark-slant::before{content:"";position:absolute;inset:0 -.35em 0 -.25em;z-index:-1;border-radius:.125rem;background:var(--rich-accent);transform:skewX(-6deg);transition:filter 300ms ease,transform 300ms ease;}.rich-mark-glow{color:var(--rich-accent);font-weight:700;text-shadow:0 0 5px var(--rich-accent),0 0 15px color-mix(in oklch,var(--rich-accent) 50%,transparent);transition:text-shadow 300ms ease;}.rich-mark-under{color:inherit;font-weight:600;}.rich-mark-under::after{content:"";position:absolute;left:0;bottom:-2px;width:100%;height:3px;border-radius:2px;background:var(--rich-accent);transform-origin:left;transition:transform 300ms ease;}.rich-mark-strike{color:inherit;font-weight:500;}.rich-mark-strike::after{content:"";position:absolute;left:-.1em;right:-.1em;top:50%;height:3px;border-radius:2px;background:var(--rich-accent);transform:rotate(-2deg);}.rich-mark-box{border:2px solid var(--rich-accent);border-radius:var(--dowe-radius);background:transparent;color:var(--rich-accent);padding:.25rem .75rem;font-weight:600;transition:background-color 300ms ease,box-shadow 300ms ease,transform 300ms ease;}.rich-mark-wave{color:inherit;font-weight:600;text-decoration:underline wavy var(--rich-accent);text-underline-offset:4px;transition:text-underline-offset 300ms ease;}.rich-mark-neon{color:var(--rich-accent);font-weight:700;letter-spacing:.05em;text-transform:uppercase;text-shadow:0 0 5px var(--rich-accent),0 0 10px var(--rich-accent),0 0 20px var(--rich-accent),0 0 40px var(--rich-accent);animation:dowe-rich-neon-flicker 2s ease-in-out infinite;}.rich-mark-pop{color:var(--rich-accent);font-weight:700;text-shadow:1px 1px 0 color-mix(in oklch,var(--rich-accent) 80%,black),2px 2px 0 color-mix(in oklch,var(--rich-accent) 60%,black),3px 3px 0 color-mix(in oklch,var(--rich-accent) 40%,black);transition:text-shadow 200ms ease,transform 200ms ease;}.rich-mark-tag{border-radius:var(--dowe-radius);background:color-mix(in oklch,var(--rich-accent) 15%,var(--dowe-surface));color:var(--rich-accent);padding:.25rem .75rem;font-weight:700;box-shadow:0 2px 8px color-mix(in oklch,var(--dowe-backgroundText) 10%,transparent);transition:box-shadow 300ms ease,transform 300ms ease;}.rich-mark-mark:hover{filter:brightness(1.1);transform:scale(1.02);}.rich-mark-grad:hover{filter:brightness(1.15);}.rich-mark-pill:hover{background:color-mix(in oklch,var(--rich-accent) 10%,transparent);transform:translateY(-1px);}.rich-mark-slant:hover::before{filter:brightness(1.1);transform:skewX(-6deg) scale(1.05);}.rich-mark-glow:hover{text-shadow:0 0 10px var(--rich-accent),0 0 25px var(--rich-accent),0 0 40px color-mix(in oklch,var(--rich-accent) 50%,transparent);}.rich-mark-under:hover::after{transform:scaleX(1.1);}.rich-mark-box:hover{background:color-mix(in oklch,var(--rich-accent) 10%,transparent);box-shadow:0 4px 12px color-mix(in oklch,var(--rich-accent) 20%,transparent);transform:translateY(-2px);}.rich-mark-wave:hover{text-underline-offset:6px;}.rich-mark-pop:hover{transform:translate(-2px,-2px);text-shadow:1px 1px 0 color-mix(in oklch,var(--rich-accent) 80%,black),2px 2px 0 color-mix(in oklch,var(--rich-accent) 60%,black),3px 3px 0 color-mix(in oklch,var(--rich-accent) 40%,black),4px 4px 0 color-mix(in oklch,var(--rich-accent) 20%,black),5px 5px 0 color-mix(in oklch,var(--rich-accent) 10%,black);}.rich-mark-tag:hover{box-shadow:0 4px 16px color-mix(in oklch,var(--dowe-backgroundText) 15%,transparent);transform:translateY(-2px);}.rich-mark.is-primary{--rich-accent:var(--dowe-primary);--rich-on-accent:var(--dowe-primaryText);--rich-soft-accent:var(--dowe-softPrimary);}.rich-mark.is-secondary{--rich-accent:var(--dowe-secondary);--rich-on-accent:var(--dowe-secondaryText);--rich-soft-accent:var(--dowe-softSecondary);}.rich-mark.is-tertiary{--rich-accent:var(--dowe-tertiary);--rich-on-accent:var(--dowe-tertiaryText);--rich-soft-accent:var(--dowe-softTertiary);}.rich-mark.is-muted{--rich-accent:var(--dowe-muted);--rich-on-accent:var(--dowe-mutedText);--rich-soft-accent:var(--dowe-softMuted);}.rich-mark.is-success{--rich-accent:var(--dowe-success);--rich-on-accent:var(--dowe-successText);--rich-soft-accent:var(--dowe-softSuccess);}.rich-mark.is-info{--rich-accent:var(--dowe-info);--rich-on-accent:var(--dowe-infoText);--rich-soft-accent:var(--dowe-softInfo);}.rich-mark.is-warning{--rich-accent:var(--dowe-warning);--rich-on-accent:var(--dowe-warningText);--rich-soft-accent:var(--dowe-softWarning);}.rich-mark.is-danger{--rich-accent:var(--dowe-danger);--rich-on-accent:var(--dowe-dangerText);--rich-soft-accent:var(--dowe-softDanger);}@keyframes dowe-rich-neon-flicker{0%,100%{opacity:1;}50%{opacity:.9;}52%{opacity:1;}54%{opacity:.95;}}@media(prefers-reduced-motion:reduce){.rich-mark{animation:none!important;transition:none!important;}.rich-mark::before,.rich-mark::after{transition:none!important;}}"#
}
